const etThreads = [
  {id:'T1',account:'Contoso',title:'账单中心二期 SOW',style:'瀑布',status:'待甲方签认',owner:'morgan',project:'p1 账单中心',requirement:'待签认后转为 R-21 v1',baseline:'BL-7 v1',signed:false,converted:false,
    source:'《账单中心二期需求说明书.docx》',summary:'3 个阶段、5 个里程碑、14 条需求项、21 条验收标准、2 条范围外',
    items:etTitles.map((title,n)=>({id:'条目 '+(n+1),phase:n<4?'阶段一 · 基础账单':n<10?'阶段二 · 导出能力':'阶段三 · 验收移交',title,criteria:[`验收 ${n+1}：当你使用${title}时，系统应按需求说明书返回可核对的结果。`,...(n<7?[`验收 ${n+15}：当输入无效时，系统应提供明确提示且不泄露数据。`]:[])].join('\n'),priority:n<7?'高':'中',ref:'需求说明书 §'+(n<4?'2':n<10?'3':'4')+'.'+(n+1),out:false})),
    outside:['历史账单数据回填','第三方支付渠道对接'],milestones:['M1 基础账单 · 10-20','M2 导出能力 · 10-27','M3 权限审计 · 10-29','M4 甲方验收 · 11-03','M5 上线移交 · 11-05'],
    messages:[{by:'Lee · 甲方',text:'已上传《账单中心二期需求说明书.docx》，请按阶段整理范围和验收标准。'},{by:'Iris 起草 · Morgan 批准发送',text:'已整理需求确认单 BL-7 v1，请 Lee 签认。签认前不会将本主题转为内部需求。'}],
    drafts:[{id:1,text:'我们承诺 M2 导出能力在 10-27 交付，本期包含审计角色金额导出，价格保持不变。',commitment:true},{id:2,search:{...mdSearchExample,pending:true},text:'已整理 14 条需求项与 21 条验收标准，请查看来源段落；Zhao 可只读查看，Lee 可签认。',commitment:false}],notes:['Morgan：@Ada 请核对审计角色的金额字段范围，先给我结论，再决定是否向甲方提问。']},
  {id:'T2',account:'Contoso',title:'十月优化清单',style:'清单',status:'整理中',owner:'morgan',project:'p1 账单中心',requirement:'2 条已纳入现有需求',baseline:'待生成',signed:false,converted:false,source:'甲方粘贴的 8 条清单',summary:'已确认 3、澄清中 2、已纳入需求 2、不做 1（附理由）',
    items:['列表筛选记忆','账期默认值','导出提示','金额显示精度','审计角色权限','分页性能','文件名含账期','历史数据回填'].map((title,n)=>({id:'清单 '+(n+1),phase:'十月优化',title,criteria:'当你使用该功能时，系统应符合逐条确认的行为。',priority:'中',ref:'粘贴清单第 '+(n+1)+' 条',out:n===7,status:['已确认','已确认','已确认','澄清中','澄清中','已纳入需求','已纳入需求','不做'][n]})),outside:['历史数据回填：本期无迁移预算，甲方已知悉理由'],milestones:['十月清单 · 日期待人确认'],messages:[{by:'Lee · 甲方',text:'请核对我粘贴的 8 条优化清单。'},{by:'Morgan · 对接人',text:'已纳入需求的 2 条来自已有签认基线；剩余清单确认后仍需签认才能开工。历史数据回填本期不做，理由是本期无迁移预算。'}],drafts:[{id:1,text:'请补充金额显示精度的示例，以及审计角色需要查看的字段。',commitment:false}],notes:['Morgan：@Ada 协助整理两条澄清项的验收示例。']},
  {id:'T3',account:'Contoso',title:'导出权限问题',style:'对话',status:'快速通道',owner:'morgan',project:'p1 账单中心',requirement:'已转为变更并通知甲方',baseline:'无需签认 · 容差判定',signed:false,converted:true,source:'门户自由对话',summary:'按时间、成本与范围容差判定无需签认',items:[{id:'澄清 1',phase:'权限澄清',title:'审计角色导出权限',criteria:'当审计角色导出时，系统应排除金额字段。',priority:'高',ref:'门户对话 · Lee 的确认回复',out:false}],outside:['审计角色金额导出'],milestones:['沿用已有里程碑'],messages:[{by:'Lee · 甲方',text:'审计角色需要导出，但不应看到金额字段。'},{by:'Morgan · 对接人',text:'已确认审计角色不可导出金额字段。本次调整按容差判定无需签认，已转为变更并通知你。'}],drafts:[],notes:['Morgan：容差判定为未越界，确认通知已发出。']},
  {id:'F1',account:'Fabrikam',title:'结算对账接口',style:'清单',status:'已转需求',owner:'chen',project:'p2 商户控制台',requirement:'已转内部需求',baseline:'已签认的接口清单 v1',signed:true,converted:true,source:'甲方接口清单',summary:'2 条接口需求，已签认并转换',items:[{id:'接口 1',phase:'对账',title:'结算明细查询',criteria:'当你查询账期时，系统应返回该账期结算明细。',priority:'高',ref:'接口清单 §1',out:false},{id:'接口 2',phase:'对账',title:'差异结果查询',criteria:'当你查询差异时，系统应返回可追溯的差异明细。',priority:'中',ref:'接口清单 §2',out:false}],outside:['历史差异修复'],milestones:['接口联调 · 日期待确认'],messages:[{by:'甲方联系人',text:'接口清单已签认。'},{by:'对接人',text:'已转为内部需求，后续同步里程碑进度。'}],drafts:[],notes:['阿澈：接口联调计划待确认。']}
];
const etInputStyle = 'width:100%;padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--fg);font:inherit';
function etEsc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function etThread(id=etState.current){return etThreads.find(t=>t.id===id);}
function etHuman(t){return etState.actor===t.owner;}
function etBtn(text,action,kind='',reason=''){return `<button type="button" class="btn ${kind}" ${reason?'disabled title="'+etEsc(reason)+'"':''} onclick="${action}">${text}</button>${reason?`<span class="muted xs">${etEsc(reason)}</span>`:''}`;}
function etBadge(text){return `<span class="badge ${text==='已转需求'||text==='已签认可转换'?'b-ok':text==='待甲方签认'?'b-warn':'b-info'}">${etEsc(text)}</span>`;}
function etTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;}
function etStatus(t){return etState.preview[t.id]||t.status;}
function etPreview(status){const t=etThread();etState.preview[t.id]=status;route();}
function etFilter(value){etState.filter=value;route();}
function etIdentity(value){etState.actor=value;route();}
function etModal(title,body,actions){openModal(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">${title}</h3>${etBtn('关闭','closeModal()','ghost sm')}</div>${body}<div class="row wrap">${actions}</div></div>`,true);}
function etDraftAction(index,action){
  const t=etThread(),d=t.drafts[index];if(!d)return;
  if(!etHuman(t))return toast('仅人类对接人可批准外发');
  if(action==='discard')return etModal('丢弃 Agent 草稿',`<div class="note danger">丢弃后该草稿将从待批准列表移除，不会发送给甲方。需重新认证。</div><label class="row"><input id="et_reauth" type="checkbox">确认重新认证（原型模拟）</label>`,etBtn('确认丢弃',`etDiscard(${index})`,'danger'));
  etModal(action==='edit'?'修改后发送':'批准发送',`${d.commitment?'<div class="note danger">需对接人亲自确认承诺：发送后，范围、日期和价格将成为甲方可见的承诺。</div>':''}<label class="stack">外发内容<textarea id="et_reply" rows="5" style="${etInputStyle}">${etEsc(d.text)}</textarea></label>${d.search?mdSearchCard(d.search):''}${d.commitment?'<label class="row"><input id="et_commitment" type="checkbox">我已亲自确认范围、日期、价格与承诺</label>':''}`,etBtn('确认发送',`etSend(${index})`,'primary'));
}
function etSend(index){const t=etThread(),d=t.drafts[index];if(!d||!etHuman(t))return;const text=document.getElementById('et_reply').value.trim();if(!text)return toast('请填写外发内容');if(d.commitment&&!document.getElementById('et_commitment').checked)return toast('请亲自确认承诺');t.messages.push({by:'Iris 起草 · '+(t.owner==='morgan'?'Morgan':'阿澈')+' 批准发送',text,search:d.search?{...d.search,pending:false}:null});t.drafts.splice(index,1);closeModal();route();toast('已批准发送，甲方会话可见');}
function etDiscard(index){if(!etHuman(etThread()))return;if(!document.getElementById('et_reauth').checked)return toast('需重新认证，请完成原型确认');etThread().drafts.splice(index,1);closeModal();route();toast('草稿已丢弃');}
function etNote(){const el=document.getElementById('et_note'),text=el.value.trim();if(!text)return toast('请填写内部旁注');etThread().notes.push((etState.actor==='iris'?'Iris':'你')+'：'+text);route();toast('已添加内部旁注，甲方不可见');}
function etEditable(t){return !t.signed&&!t.converted&&etStatus(t)==='整理中';}
function etEditItem(index){const t=etThread(),item=t.items[index];if(!item||!etEditable(t))return;etModal('编辑需求项',`${['phase','title','criteria','priority'].map((key,n)=>`<label class="stack">${['阶段','需求项','验收标准（每条一行，保留编号）','优先级'][n]}<textarea id="et_${key}" rows="${key==='criteria'?3:1}" style="${etInputStyle}">${etEsc(item[key])}</textarea></label>`).join('')}<div class="note info">来源段落引用：${etEsc(item.ref)}。编辑仅改草案，不改变已发送或已签认的确认单。</div>`,etBtn('保存草案',`etSaveItem(${index})`,'primary'));}
function etSaveItem(index){const t=etThread();if(!etEditable(t))return;const values=['phase','title','criteria','priority'].map(k=>document.getElementById('et_'+k).value.trim());if(values.some(v=>!v))return toast('阶段、需求项、验收标准、优先级均必填');['phase','title','criteria','priority'].forEach((key,n)=>t.items[index][key]=values[n]);closeModal();route();toast('需求草案已保存');}
function etTransform(index,action){const t=etThread();if(!etEditable(t))return;const item=t.items[index];if(action==='merge'){const next=t.items[index+1];if(!next)return;item.title+='；'+next.title;item.criteria+='\n'+next.criteria;item.ref+='；'+next.ref;item.out=item.out&&next.out;t.items.splice(index+1,1);}if(action==='split'){etModal('拆分需求项',`<div class="note info">请填写拆出的需求项与验收标准；原条目保留，来源引用继承。</div><label class="stack">拆出的需求项<input id="et_split_title" style="${etInputStyle}"></label><label class="stack">验收标准<textarea id="et_split_criteria" style="${etInputStyle}"></textarea></label>`,etBtn('确认拆分',`etSplit(${index})`,'primary'));return;}if(action==='outside'){etModal('标记范围外',`<div class="note danger">该条目将从本期范围移出，影响后续确认单。需重新认证。已签认基线不可在此修改。</div><label class="row"><input id="et_reauth" type="checkbox">确认重新认证（原型模拟）</label>`,etBtn('确认标范围外',`etOutside(${index})`,'danger'));return;}route();}
function etSplit(index){const t=etThread();if(!etEditable(t))return;const title=document.getElementById('et_split_title').value.trim(),criteria=document.getElementById('et_split_criteria').value.trim();if(!title||!criteria)return toast('请填写需求项和验收标准');t.items.splice(index+1,0,{...t.items[index],id:'拆分 '+(t.items.length+1),title,criteria});closeModal();route();}
function etOutside(index){const t=etThread();if(!etEditable(t))return;if(!document.getElementById('et_reauth').checked)return toast('需重新认证');t.items[index].out=true;closeModal();route();}
function etGenerate(){const t=etThread();if(!etHuman(t)||!etEditable(t))return;etModal('生成需求确认单并发送签认',`<div class="note warn">仅人类对接人可发起。请亲自核对范围、日期、价格与承诺；会话不替代签认基线。</div><div class="kv"><span>确认单</span><b>${etEsc(t.id==='T1'?'BL-7 v1':'十月清单确认单 v1')}</b><span>本期需求</span><b>${t.items.filter(i=>!i.out).length} 条</b><span>签认人</span><b>Lee · Zhao 只读</b></div><label class="row"><input id="et_commitment" type="checkbox">我已核对确认单及其承诺</label>`,etBtn('发送给甲方签认','etPublish()','primary'));}
function etPublish(){const t=etThread();if(!etHuman(t)||!etEditable(t))return;if(!document.getElementById('et_commitment').checked)return toast('请亲自核对确认单及其承诺');t.baseline=t.id==='T1'?'BL-7 v1':'十月清单确认单 v1';t.snapshot=JSON.parse(JSON.stringify({items:t.items,milestones:t.milestones,outside:t.outside}));t.status='待甲方签认';delete etState.preview[t.id];t.messages.push({by:'Morgan · 对接人',text:'已发送需求确认单 '+t.baseline+'，请 Lee 签认；Zhao 可只读查看。'});closeModal();route();toast('确认单已发送，等待甲方签认');}
function etConvert(){const t=etThread();if(!etHuman(t)||etStatus(t)!=='已签认可转换'||t.converted)return;/* 状态预览仅模拟签认，不代表真实甲方回执。 */t.signed=true;t.converted=true;t.status='已转需求';t.requirement=t.id==='T1'?'R-21 v1':'内部需求草案';delete etState.preview[t.id];route();toast('已按签认样例转换为内部需求（原型模拟）');}
function etConfirmGoal(){const t=etThread();if(!etHuman(t)||!t.converted)return;t.goalConfirmed=true;route();toast('项目目标与关键结果草案已由人确认');}
function etSettings(){const t=etThread();openDrawer(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">对接组设置</h3>${etBtn('关闭','closeDrawer()','ghost sm')}</div>${card('对接组成员',`<div class="stack">${who(t.owner)}<p>人类对接人 · 负责承诺</p>${who('iris')}<p>协调员 Agent · 起草、整理、提问、汇报</p><label class="row"><input type="checkbox" ${etState.ada?'checked':''} ${etHuman(t)?'':'disabled'} onchange="etState.ada=this.checked">领域 Agent Ada · 按需加入</label>${etHuman(t)?'':'<p class="muted small">仅人类对接人可调整对接组。</p>'}</div>`)}${card('Agent 自主度',`<p>默认：所有外发需人批准。</p><label class="row"><input type="checkbox" ${etState.autonomous?'checked':''} ${etHuman(t)?'':'disabled'} onchange="etState.autonomous=this.checked;toast(this.checked?'事实与进度类回答可自行发送':'所有外发需人批准')">Agent 可自行回答事实与进度类问题</label><div class="note danger">范围 / 日期 / 价格 / 承诺始终需人。此设置不解除承诺审批。</div>${etHuman(t)?'':'<p class="muted small">Agent 身份不能变更自主度。</p>'}`)}${card('渠道',etTable(['渠道','状态','线程映射'],['门户','邮件线程','API'].map(c=>`<tr><td>${c}</td><td>已启用</td><td>${etEsc(t.id)} · ${etEsc(t.title)}</td></tr>`).join(''))+'<p class="note info">即时通讯（IM）连接器：第二版（v2），当前不可用。</p>')}<p class="muted xs">设置仅保存在浏览器内存，刷新后恢复默认。</p></div>`);}
function etObject(kind){const t=etThread();const data={change:['变更 IN-2042','超出时间容差 · 待甲方确认','portal-change-approval/IN-2042'],delivery:['交付包 BIL#3','待验收 · 仅含团队已接受（L3）的工作项','portal-accept'],requirement:['内部需求 R-21 v1','签认基线：BL-7 v1 · 项目 p1 账单中心','requirement/R-12'],work:['任务与执行','计划（迭代）→ 任务 → 执行 → 内部质量门 → 团队接受 → 交付','work/p1']}[kind];if(!data)return;openDrawer(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">${data[0]}</h3>${etBtn('返回对接工作台','closeDrawer()','ghost sm')}</div>${card('对象状态',`<div class="kv"><span>状态 / 链路</span><b>${data[1]}</b><span>当前主题</span><b>${etEsc(t.title)}</b><span>负责人</span><b>${etEsc(PEOPLE[t.owner].n)}</b></div>`)}${card('查看完整对象',`<p>在新标签页查看，当前对接工作台保留。</p><a class="btn" href="#/${data[2]}" target="_blank" rel="noopener">${I('external-link')}打开完整对象${kind==='requirement'?'（R-12 示例）':''}</a>`)}${card('可见范围','<p>甲方只看到里程碑级进度与交付验收，不看到内部旁注、内部返工或内部验收记录。</p>')}</div>`);}
PAGES['engagements']=()=>{
  const filtered=etThreads.filter(t=>etState.filter==='全部'||etState.filter==='我的对接'&&t.owner===etState.actor||etState.filter==='待批准草稿'&&t.drafts.length||etState.filter==='待甲方签认'&&t.status==='待甲方签认');
  return head('项目 · 团队级','甲方对接','按甲方账户汇集会话，每个需求主题独立成线程。人类对接人负责承诺，Agent 协助整理。',`<label class="row small">当前身份<select onchange="etIdentity(this.value)"><option value="morgan" ${etState.actor==='morgan'?'selected':''}>你 · Morgan</option><option value="iris" ${etState.actor==='iris'?'selected':''}>Agent Iris</option><option value="chen" ${etState.actor==='chen'?'selected':''}>你 · 阿澈</option></select></label>`)+
    card('待你处理',`<div class="row wrap"><div class="kpi"><b>${etThreads.filter(t=>t.owner===etState.actor).length}</b><span>你的对接线程</span></div><div class="kpi"><b>${etThreads.filter(t=>t.owner===etState.actor).reduce((n,t)=>n+t.drafts.length,0)}</b><span>Agent 草稿待批准</span></div><div class="kpi"><b>${etThreads.filter(t=>t.status==='待甲方签认').length}</b><span>待甲方签认</span></div></div><p class="muted small">Agent 身份可整理和起草，不能批准外发或确认承诺。</p>`)+
    card('会话筛选',`<div class="row wrap">${['全部','我的对接','待批准草稿','待甲方签认'].map(f=>`<button class="chip ${etState.filter===f?'on':''}" aria-pressed="${etState.filter===f}" onclick="etFilter('${f}')">${f}</button>`).join('')}</div>`)+
    etAccounts.map(a=>card(a.name,`<p class="muted small">${a.contacts}</p>${etTable(['线程','风格','状态','对接人','待你处理','关联项目 / 需求'],filtered.filter(t=>t.account===a.name).map(t=>`<tr><td><a href="#/engagement/${t.id}">${t.id} · ${etEsc(t.title)}</a></td><td>${t.style}</td><td>${etBadge(t.status)}</td><td>${who(t.owner)}</td><td>${t.drafts.length?(t.owner===etState.actor?t.drafts.length+' 条 Agent 草稿待批准':'由 '+PEOPLE[t.owner].n+' 批准 '+t.drafts.length+' 条草稿'):'暂无待批准草稿'}</td><td>${etEsc(t.project)}<p class="muted small">${etEsc(t.requirement)}</p></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">当前筛选下暂无对接线程</div></td></tr>')}`)).join('')+
    card('来件记录',`<p>旧的来件记录仍可在〔来件记录〕查看。</p>${etBtn('来件记录',"go('intakes')",'ghost')}`);
};
PAGES['engagement']=(id)=>{
  const t=etThread(id);if(!t)return head('甲方对接','未找到对接线程','请返回列表选择已有主题。',etBtn('返回甲方对接',"go('engagements')",'ghost'))+card('线程标识',`<p>${etEsc(id||'未指定')}</p>`)+card('可用线程','<p>T1、T2、T3、F1</p>')+card('导航',etBtn('查看线程列表',"go('engagements')"));
  etState.current=t.id;const status=etStatus(t),human=etHuman(t),editable=etEditable(t),reason=human?'':'仅人类对接人可批准外发',editReason=editable?'':t.signed||t.converted?'已签认基线不可直接修改':'请切换「整理中」预览后编辑草案';
  return head(t.account+' · '+t.id,t.title,'对话与甲方所见一致；Agent 草稿及内部旁注仅团队可见。',etBtn('返回甲方对接',"go('engagements')",'ghost')+etBtn('对接组设置','etSettings()')+`<label class="row small">身份<select onchange="etIdentity(this.value)"><option value="${t.owner}" ${human?'selected':''}>你 · ${etEsc(PEOPLE[t.owner].n)}</option><option value="iris" ${etState.actor==='iris'?'selected':''}>Agent Iris</option></select></label>`)+
    card('状态预览',`<div class="row wrap">${['整理中','待甲方签认','已签认可转换','快速通道'].map(s=>`<button class="chip ${status===s?'on':''}" aria-pressed="${status===s}" onclick="etPreview('${s}')">${s}</button>`).join('')}${etBadge(status)}</div><p class="muted xs">预览仅模拟状态与按钮条件，不产生真实甲方签认；快速通道只适用于按容差判定无需签认的小型对话需求。</p>${status==='快速通道'&&t.style!=='对话'?'<div class="note warn">本主题为'+t.style+'式，仍须甲方签认，不能通过快速通道开工。</div>':''}`)+
    `<div class="grid g12"><div class="c6 stack">`+
    card('与甲方的对话',`<div class="stack">${t.messages.map(m=>`<div class="bubble"><b class="small">${etEsc(m.by)}</b><p>${etEsc(m.text)}</p>${m.search?mdSearchCard(m.search):''}</div>`).join('')}<div class="decision-card"><b>澄清问题卡</b><p>审计角色是否可导出金额字段？</p>${etBadge(t.id==='T3'?'已确认：不可导出金额字段':'待甲方澄清')}</div>${t.id==='T3'?'<div class="note ok">快速通道：按时间、成本、范围容差判定无需签认，已转为变更并通知甲方。</div>':''}<div class="decision-card"><b>变更 IN-2042</b><p>超出时间容差 · 待甲方确认</p>${etBtn('查看变更',"etObject('change')",'sm')}</div><div class="decision-card"><b>交付包 BIL#3</b><p>待验收 · 仅包含团队已接受（L3）的工作项</p>${etBtn('查看交付包',"etObject('delivery')",'sm')}</div><div class="decision-card"><b>里程碑进度卡</b><p>M2 导出能力：4 / 6 项完成，预计 10-27</p><div class="progress"><div style="width:66.67%"></div></div><p class="muted xs">由 Iris 起草、Morgan 批准后发出</p></div></div>`)+
    card('甲方附件预览',`<div class="stack">${t.id==='T1'?mdTeamAttachments(editable):'<div class="empty">本主题暂无附件</div>'}${t.mediaExtracted?'<p class="note ok">已从附件抽取 6 条需求项</p>':''}</div>`)+
    card('Agent 草稿待批准',`<div class="stack">${t.drafts.map((d,n)=>`<div class="note ${d.commitment?'danger':'info'}"><b>Iris 起草 · 待批准 · 甲方不可见</b>${d.commitment?'<p><b>需对接人亲自确认承诺</b></p>':''}<p>${etEsc(d.text)}</p>${d.search?mdSearchCard(d.search):''}<div class="row wrap">${etBtn('批准发送',`etDraftAction(${n},'approve')`,'primary sm',reason)}${etBtn('修改后发送',`etDraftAction(${n},'edit')`,'sm',reason)}${etBtn('丢弃',`etDraftAction(${n},'discard')`,'danger sm',reason)}</div><p class="xs">丢弃将移除草稿且不外发；需重新认证。</p></div>`).join('')||'<div class="empty">暂无待批准草稿，已发内容见上方对话。</div>'}</div>`)+
    card('内部旁注线程',`<span class="badge b-warn">甲方不可见</span><div class="stack">${t.notes.map(n=>`<div class="bubble">${etEsc(n)}</div>`).join('')}<label class="stack">团队讨论 · 可提及 @Ada<textarea id="et_note" onpaste="mdPaste(event,'engagement-'+etState.current)" rows="2" style="${etInputStyle}" placeholder="给对接组的内部旁注"></textarea></label>${mdComposerTools({id:"engagement-"+t.id,input:"et_note",team:true,authorized:t.id==='T1'})}${etBtn('添加内部旁注','etNote()','sm')}</div><p class="muted xs">内部返工与内部验收记录不外发；需求歧义先交人类负责人决定是否向甲方澄清。</p>`)+
    `</div><div class="c6 stack">`+
    card('需求草案构建器',`<div class="kv"><span>来源</span><b>${etEsc(t.source)}</b><span>抽取结果</span><b>${etEsc(t.summary)}</b><span>对接人</span><b>${etEsc(PEOPLE[t.owner].n)} · 人类负责承诺</b></div><p class="note info">${editReason||'可编辑、合并相邻条目、拆分或标记范围外；来源引用保留。'}</p>${etTable(['阶段 / 需求项','验收标准 / 优先级','来源 / 操作'],t.items.map((item,n)=>`<tr><td>${etEsc(item.phase)}<p><b>${etEsc(item.title)}</b></p>${item.out?'<span class="badge b-danger">范围外</span>':item.status?etBadge(item.status):''}</td><td style="white-space:pre-line">${etEsc(item.criteria)}<p>优先级：${etEsc(item.priority)}</p></td><td><span class="muted xs">${etEsc(item.ref)}</span><div class="row wrap">${etBtn('编辑',`etEditItem(${n})`,'sm',editable?'':'草案已锁定')}${etBtn('合并',`etTransform(${n},'merge')`,'sm',!editable?'草案已锁定':n===t.items.length-1?'没有下一条可合并':'')}${etBtn('拆分',`etTransform(${n},'split')`,'sm',editable?'':'草案已锁定')}${etBtn('标范围外',`etTransform(${n},'outside')`,'danger sm',!editable?'草案已锁定':item.out?'已标记范围外':'')}</div></td></tr>`).join(''))}`)+
    card('里程碑与范围外',`<div class="stack">${t.milestones.map(m=>`<div class="row">${I('flag')}<span>${etEsc(m)}</span></div>`).join('')}<div class="sep"></div><b>范围外</b>${[...t.outside,...t.items.filter(i=>i.out).map(i=>i.title)].map(o=>`<p class="muted small">${etEsc(o)}</p>`).join('')}</div>`)+
    card('需求确认单与签认',`<div class="kv"><span>确认单</span><b>${etEsc(t.baseline)}</b><span>签认状态</span><b>${status==='已签认可转换'?'Lee 已签认（状态预览）':t.signed?'已签认':t.id==='T3'?'按容差判定无需签认':status==='待甲方签认'?'待甲方签认':'整理中'}</b><span>联系人</span><b>${t.account==='Contoso'?'Lee 可签认 · Zhao 只读':'签认权限待核对'}</b><span>基线规则</span><b>瀑布 / 清单须签认后开工</b></div>${etBtn(t.id==='T1'?'生成需求确认单 BL-7 v1 并发给甲方签认':'生成需求确认单并发给甲方签认','etGenerate()','primary',!human?'仅人类对接人可生成并发送确认单':!editable?editReason:'')}<p class="muted xs">已发送 / 已签认的确认单保持原版本；后续范围变更走变更确认。</p>`)+
    `</div><div class="c12">`+card('转换链路',`<div class="note info">内部流程按项目与场景灵活调整，甲方只看到里程碑级进度。</div>${etTable(['步骤','关联对象 / 内容','状态','操作'],`<tr><td>签认基线</td><td>${etEsc(t.baseline)}</td><td>${t.converted?'已转换':status==='已签认可转换'?'已签认可转换':'待签认'}</td><td>${etBtn('转为内部需求','etConvert()','primary sm',!human?'仅人类对接人可转换':t.converted?'已转换，无需重复':status!=='已签认可转换'?'甲方签认后可用':'')}</td></tr><tr><td>内部需求</td><td>${t.id==='T1'?'R-21 v1 · p1 账单中心':etEsc(t.requirement)}</td><td>${t.converted?'已转需求':'尚未创建'}</td><td>${etBtn('查看需求示例',"etObject('requirement')",'sm',t.converted?'':'签认并转换后可用')}</td></tr><tr><td>项目目标 / 关键结果草案</td><td>Iris 起草：让账单导出可追溯；关键结果：6 项导出能力通过验收</td><td>${t.goalConfirmed?'人已确认':t.converted?'待人确认':'转换后起草'}</td><td>${etBtn('人确认','etConfirmGoal()','sm',!human?'Agent 不可确认目标或关键结果':!t.converted?'需先转换为内部需求':t.goalConfirmed?'已经确认':'')}</td></tr><tr><td>计划（迭代）</td><td>十月账单迭代 · 负责人 Morgan · 日期待确认</td><td>${t.goalConfirmed?'待确认计划':'待目标确认'}</td><td>按项目与场景调整</td></tr><tr><td>任务</td><td>任务分解 → 执行 → 内部质量门 → 团队接受 → 交付</td><td>${t.converted?'待计划与就绪检查':'尚未分解'}</td><td>${etBtn('查看项目任务',"etObject('work')",'sm',t.converted?'':'转换后可查看关联任务')}</td></tr>`)}<p class="muted xs">Agent 提交执行结果仅为「已声明完成（未验证）」；内部验收通过后仍须团队接受。此处确认草案不派发任务。</p>`)+`</div></div>`;
};
TITLES['engagements']='甲方对接';
TITLES['engagement']='对接工作台';
NAVPARENT['engagements']='projects';
NAVPARENT['engagement']='engagements';
